import { L, type JourneyInteractiveSection } from "./genesis-interactive";
import type { BibleRef } from "./references";

/**
 * Camada interativa de Juízes: paradas, quiz, família e tempo por movimento.
 * Lugares em places.ts + judges-places.ts; pessoas em journeyPeople + judges-people.ts.
 *
 * ESTADO: PENDENTE DE REVISÃO HUMANA. Textos escritos para a Jornada a partir do texto
 * bíblico citado em cada `ref`; ainda não passaram por revisão teológica nem de tradução.
 * Português na norma brasileira (chave pt-PT, que também serve o pt-BR).
 * Datas: cronologia tradicional (saída do Egito c. 1446 a.C.; Jz 11:26 dá cerca de 300 anos
 * entre a conquista e Jefté), todas aproximadas. Os episódios de Jz 17–21 não trazem data
 * e parecem ser do começo do período (Jz 18:30; 20:28).
 * Gravuras: Julius Schnorr von Carolsfeld, "Die Bibel in Bildern" (1860), domínio público.
 */
export const judgesReviewStatus = "pendente-revisao-humana" as const;

const jz = (chapter: number, verse?: number, endVerse?: number, endChapter?: number): BibleRef =>
  ({ book: "judges", chapter, verse, endVerse, endChapter });

const SCHNORR = { artist: "Julius Schnorr von Carolsfeld", year: "1860", license: "PD" };
const commons = (n: string) => `https://commons.wikimedia.org/wiki/File:Schnorr_von_Carolsfeld_Bibel_in_Bildern_1860_${n}.png`;

